from jsonb_to_recordset($wall_questions$[{"id":"u01_l03_q186","lesson_id":"u01_l03","difficulty":"medium","prompt":"إذا بيّن متعلم أن أحكام الميراث تنظم انتقال المال بعد الوفاة، فما وجه الإعجاز الذي يتصل بهذا البيان؟","options":[{"id":"o4","text":"تفسير ظاهرة مختبرية محتملة"},{"id":"o3","text":"التناسب الصوتي بين حروف الكلمات"},{"id":"o2","text":"التنبؤ بتوقيت حدث غيبي بعينه"},{"id":"o1","text":"القدرة التشريعية على تنظيم حقوق الناس"}],"correct_id":"o1","explanation":"ذكر الكتاب أحكام الميراث من الشواهد على الإعجاز التشريعي.","page":24},{"id":"u01_l03_q188","lesson_id":"u01_l03","difficulty":"medium","prompt":"في مثال مراحل خلق الجنين، كيف يخدم تأمل المعنى اللغوي للفظة مع المعرفة العلمية الثابتة فهم النص؟","options":[{"id":"o2","text":"يبيح تبديل ألفاظ الآيات للوصول إلى معنى جديد"},{"id":"o1","text":"يوضح دقة التعبير دون تحميله فرضيات غير مستقرة"},{"id":"o4","text":"ينفي الحاجة إلى معنى الكلمة في العربية"},{"id":"o3","text":"يجعل كل تفسير مؤقت حكمًا قطعيًا"}],"correct_id":"o1","explanation":"ربط الدرس استعمال لفظة العلقة بدقة الإشارة وبما استقر من علم الأجنة.","page":25},{"id":"u01_l04_q106","lesson_id":"u01_l04","difficulty":"medium","prompt":"ما الدلالة التربوية لقصة الحسن والحسين مع الرجل الذي لم يحسن الوضوء؟","options":[{"id":"o1","text":"تصحيح الخطأ بأسلوب يحفظ كرامة المتعلم"},{"id":"o2","text":"أن الإحراج العلني أسرع طرق التعليم"},{"id":"o3","text":"أن النصح يستلزم القسوة"},{"id":"o4","text":"أن الخطأ يترك دون بيان مطلقًا"}],"correct_id":"o1","explanation":"توضح القصة استخدام القدوة والنصح غير المحرج.","page":31},{"id":"u01_l04_q113","lesson_id":"u01_l04","difficulty":"medium","prompt":"ما المعنى الذي مثله أصحاب أسفل السفينة عندما أرادوا خرق موضعهم؟","options":[{"id":"o2","text":"كل تصرف فردي لا يمس المجتمع"},{"id":"o1","text":"قد يترتب على التصرف الفردي ضرر عام"},{"id":"o4","text":"خطر الفعل يختص بمن قام به دائمًا"},{"id":"o3","text":"لا يجوز الحصول على الماء من السفينة"}],"correct_id":"o1","explanation":"يوضح المثل أن ترك الإضرار المشترك قد يؤدي إلى هلاك الجميع.","page":30},{"id":"u01_l04_q117","lesson_id":"u01_l04","difficulty":"medium","prompt":"أي نتيجة تربوية تظهر من إقرار الرجل بفضل وضوء الحسن والحسين بعد مشاهدتهما؟","options":[{"id":"o3","text":"أن الرؤية لا تفيد في تعليم المهارة"},{"id":"o1","text":"أن التعلم بالقدوة قد يصحح الخطأ دون جرح الكرامة"},{"id":"o2","text":"أن التوبيخ العلني شرط لقبول النصيحة"},{"id":"o4","text":"أن تجنب بيان الخطأ هو المطلوب دائمًا"}],"correct_id":"o1","explanation":"أظهرت القصة أثر القدوة الهادئة في إقناع الرجل وتصحيح وضوئه.","page":31},{"id":"u01_l04_q118","lesson_id":"u01_l04","difficulty":"hard","prompt":"لو رأى راكب السفينة من يتسبب بخطر شامل لكنه قال «هذه حريته في مكانه»؛ أي خطأ يستهدفه المثل النبوي؟","options":[{"id":"o4","text":"التعاون لحماية المكان العام"},{"id":"o3","text":"منع التصرف الذي يهلك الجميع"},{"id":"o1","text":"تجاهل تعلق حقوق الآخرين بالضرر المشترك"},{"id":"o2","text":"الاهتمام بسلامة الركاب"}],"correct_id":"o1","explanation":"يكشف المثل أن ترك الإضرار بالمصلحة العامة يؤدي إلى هلاك الجميع.","page":30},{"id":"u01_l04_q121","lesson_id":"u01_l04","difficulty":"medium","prompt":"ما وجه ارتباط الأمر بالمعروف والنهي عن المنكر باستقامة المجتمع؟","options":[{"id":"o3","text":"إلغاء اختلاف قدرات الأفراد"},{"id":"o1","text":"تعزيز الخير وتقليل انتشار السلوك الضار"},{"id":"o4","text":"إشاعة عدم المبالاة بالأخطاء"},{"id":"o2","text":"تحويل النصيحة إلى تشهير دائم"}],"correct_id":"o1","explanation":"يبين المدخل أن الإصلاح يشيع المعروف ويحد من المنكر في المجتمع.","page":28},{"id":"u01_l04_q125","lesson_id":"u01_l04","difficulty":"medium","prompt":"لماذا لا يكفي الحماس وحده لممارسة الأمر بالمعروف والنهي عن المنكر؟","options":[{"id":"o1","text":"لأن الأمر يحتاج إلى علم بالحكم وأساليب الإصلاح"},{"id":"o3","text":"لأن كل منكر يجوز إزالته بالقوة"},{"id":"o4","text":"لأن النصيحة لا تتطلب معرفة"},{"id":"o2","text":"لأن الإصلاح لا يجوز أن يشارك فيه الناس"}],"correct_id":"o1","explanation":"ذكر الكتاب العلم ضمن شروط القيام بهذا الواجب.","page":30},{"id":"u01_l04_q132","lesson_id":"u01_l04","difficulty":"medium","prompt":"في مثال السفينة، ما مسؤولية الركاب الذين يعلمون أن خرقها يهدد الجميع؟","options":[{"id":"o3","text":"الانتظار حتى تغرق السفينة"},{"id":"o2","text":"ترك الخرق لأنه في موضع خاص"},{"id":"o1","text":"منع الضرر الذي يعمّ ركابها"},{"id":"o4","text":"إخفاء الخطر عن الآخرين"}],"correct_id":"o1","explanation":"يبين مثل السفينة أن منع المنكر يحفظ الجميع من الضرر.","page":29},{"id":"u01_l04_q135","lesson_id":"u01_l04","difficulty":"hard","prompt":"رأى مرشد مدرسي أن نصيحة خاصة ستصلح الخطأ دون فضيحة؛ فلماذا يُقدَّم هذا الأسلوب؟","options":[{"id":"o3","text":"لأنه يمنع تصحيح الخطأ نهائيًا"},{"id":"o2","text":"لأنه يلغي واجب نصح الآخرين"},{"id":"o4","text":"لأنه يجيز التجسس للوصول للمعلومة"},{"id":"o1","text":"لأنه يجمع الإصلاح مع حفظ كرامة المنصوح"}],"correct_id":"o1","explanation":"من آداب النصيحة الرفق والستر ومراعاة حال المنصوح.","page":30},{"id":"u01_l04_q136","lesson_id":"u01_l04","difficulty":"easy","prompt":"ما المقصود بالحكمة عند أداء واجب الأمر بالمعروف والنهي عن المنكر؟","options":[{"id":"o1","text":"اختيار الأسلوب المناسب للموقف"},{"id":"o4","text":"التشهير بالمخطئ في المجالس"},{"id":"o2","text":"الإكثار من اللوم والتهديد"},{"id":"o3","text":"ترك النصيحة في جميع المواقف"}],"correct_id":"o1","explanation":"يؤكد الكتاب اختيار الطريقة المناسبة بما يحقق الإصلاح.","page":30},{"id":"u01_l04_q137","lesson_id":"u01_l04","difficulty":"medium","prompt":"مَن حاول كشف خطأ مستور بالتنصت على زملائه حتى ينهاهم عنه؛ أي ضابط خالف؟","options":[{"id":"o4","text":"التزام الأسلوب اللطيف"},{"id":"o2","text":"التذكير بالقيم الحسنة"},{"id":"o1","text":"النهي عن التجسس وتتبع العورات"},{"id":"o3","text":"مراعاة القدرة على النصح"}],"correct_id":"o1","explanation":"نهى الدرس عن التجسس وتتبع أخطاء الناس عند ممارسة الإصلاح.","page":31},{"id":"u01_l04_q139","lesson_id":"u01_l04","difficulty":"medium","prompt":"أي عنصر جمعته قصة الحسن والحسين مع تصحيح الوضوء لرجل كبير؟","options":[{"id":"o2","text":"اتهامه بالتقصير أمام الناس"},{"id":"o1","text":"التعليم العملي دون إحراجه"},{"id":"o4","text":"انتقاد عبادته مباشرة"},{"id":"o3","text":"إبعاده عن الصلاة"}],"correct_id":"o1","explanation":"استُخدم العرض العملي اللطيف لتصحيح وضوء الرجل دون جرح مشاعره.","page":30},{"id":"u01_l04_q140","lesson_id":"u01_l04","difficulty":"medium","prompt":"ما الذي يُستفاد من اختلاف وسائل تغيير المنكر تبعًا للاستطاعة؟","options":[{"id":"o3","text":"سقوط استنكار المنكر في القلب"},{"id":"o1","text":"التكليف بالإصلاح ضمن القدرة والصلاحية"},{"id":"o2","text":"وجوب استعمال القوة لكل فرد"},{"id":"o4","text":"ترك النصح لمن يملك العلم"}],"correct_id":"o1","explanation":"يوضح الدرس مراعاة الاستطاعة والصلاحية في مراتب التغيير.","page":31},{"id":"u01_l04_q141","lesson_id":"u01_l04","difficulty":"medium","prompt":"أي عبارة تحدد نطاق المعروف والمنكر دون ربطهما بأذواق الأشخاص؟","options":[{"id":"o2","text":"يتغيران مع شهرة الفعل وحدها"},{"id":"o1","text":"يُعرَفان بالنظر إلى ما أمر به الشرع أو نهى عنه"},{"id":"o4","text":"يتحددان بعدد من يوافق عليهما"},{"id":"o3","text":"يُحكَم عليهما بمصلحة الفاعل الخاصة"}],"correct_id":"o1","explanation":"المعروف خير أمر به الشرع والمنكر ما نهى عنه، وليس مجرد عرف اجتماعي.","page":28},{"id":"u01_l04_q144","lesson_id":"u01_l04","difficulty":"medium","prompt":"نصح شاب شخصًا أكبر منه بأسلوب جارح رغم صحة الحكم الذي ذكره؛ ماذا أهمل؟","options":[{"id":"o2","text":"ضرورة معرفة الحكم قبل النصح"},{"id":"o4","text":"أصل أهمية الإصلاح"},{"id":"o3","text":"وجوب أداء الفرائض"},{"id":"o1","text":"الحكمة وحسن اختيار أسلوب النصح"}],"correct_id":"o1","explanation":"صحة المعلومة وحدها لا تكفي؛ بل ينبغي مراعاة الحكمة والرفق.","page":30},{"id":"u01_l04_q145","lesson_id":"u01_l04","difficulty":"medium","prompt":"ما الذي يجعل التعليم العملي في قصة تصحيح الوضوء أبلغ من توبيخ المخطئ؟","options":[{"id":"o4","text":"منع التصحيح أمامه"},{"id":"o3","text":"إلزامه بعدم السؤال مستقبلًا"},{"id":"o2","text":"إظهار عجز المخطئ أمام الجمهور"},{"id":"o1","text":"إتاحة الفرصة ليفهم الصواب دون إحراج"}],"correct_id":"o1","explanation":"تُبرز قصة الحسن والحسين رضي الله عنهما أسلوبًا لطيفًا لإرشاد المخطئ.","page":30},{"id":"u01_l04_q146","lesson_id":"u01_l04","difficulty":"hard","prompt":"إذا ترتب على أسلوب إنكار منكر حدوث منكر أشد منه، فأي مقصد من ضوابط الإنكار لم يتحقق؟","options":[{"id":"o1","text":"تحقيق الإصلاح ودفع الضرر لا زيادته"},{"id":"o4","text":"تجاهل اختلاف القدرة والصلاحية"},{"id":"o3","text":"عرض الخطأ أمام الحاضرين"},{"id":"o2","text":"الإكثار من الجدل في كل حالة"}],"correct_id":"o1","explanation":"يراعي الدرس مآلات تغيير المنكر والصلاحية والاستطاعة في الإصلاح.","page":31},{"id":"u01_l04_q152","lesson_id":"u01_l04","difficulty":"hard","prompt":"في قصة السفينة، ما سبب خطورة ترك مجموعة من الركاب تخرق موضعها رغم أنها تدعي ملكه؟","options":[{"id":"o4","text":"أن الإنكار يمنع الناس من استعمال الماء"},{"id":"o2","text":"أن الخرق لا يؤثر إلا في صاحب المكان"},{"id":"o1","text":"أن الضرر يتعدى أصحاب الفعل إلى جميع الركاب"},{"id":"o3","text":"أن أصحاب السفينة لا تربطهم مصلحة مشتركة"}],"correct_id":"o1","explanation":"يشبّه الحديث المجتمع بالسفينة التي يهلك ركابها إذا تُرك ما يضر الجميع.","page":30},{"id":"u01_l04_q155","lesson_id":"u01_l04","difficulty":"medium","prompt":"ماذا يُطلب من الناصح حين يحتاج المخطئ إلى وقت ليتعلم السلوك الصحيح؟","options":[{"id":"o2","text":"السخرية من جهله في كل لقاء"},{"id":"o3","text":"نشر صور خطئه قبل نصحه"},{"id":"o1","text":"الصبر والرفق وإعطاؤه فرصة للتعلم"},{"id":"o4","text":"إلزامه بعقوبة يقررها الناصح لنفسه"}],"correct_id":"o1","explanation":"أوصى الدرس بالصبر والرفق في النصيحة وتجنب الأذى والتنفير.","page":31},{"id":"u01_l04_q158","lesson_id":"u01_l04","difficulty":"hard","prompt":"إذا رأى المرء منكرًا ولم يملك وسيلة مباحة لتغييره بيده أو لسانه، فما المجال الذي يبقى له؟","options":[{"id":"o4","text":"اختلاق اتهامات جديدة لصاحبه"},{"id":"o2","text":"الاعتداء على الناس لإجبارهم"},{"id":"o1","text":"إنكاره بقلبه وعدم الرضا به"},{"id":"o3","text":"التظاهر بالموافقة عليه"}],"correct_id":"o1","explanation":"عرض الكتاب مراتب تغيير المنكر ومن بينها الإنكار بالقلب عند العجز عن غيره.","page":32},{"id":"u01_l04_q162","lesson_id":"u01_l04","difficulty":"hard","prompt":"إذا كان النصح سيؤدي إلى فساد أكبر من الخطأ الأصلي، فما الضابط الذي ينبغي مراعاته؟","options":[{"id":"o3","text":"أن يهمل تقدير النتائج على الآخرين"},{"id":"o1","text":"ألا يترتب على التغيير منكر أشد من المنكر المراد تغييره"},{"id":"o2","text":"أن يغيّر المرء كل خطأ بالقوة بنفسه"},{"id":"o4","text":"أن ينشر أخطاء المخالفين أولًا"}],"correct_id":"o1","explanation":"تضمن الدرس مراعاة المصلحة وتجنب ترتب منكر أعظم عند الإنكار.","page":29},{"id":"u01_l04_q163","lesson_id":"u01_l04","difficulty":"medium","prompt":"نصح طالب زميله بلغة مهذبة مستندًا إلى علم بحكم الفعل؛ أي ميزتين اجتمعتا في تصرفه؟","options":[{"id":"o3","text":"الاستعلاء وإساءة الظن"},{"id":"o1","text":"العلم والحكمة في أسلوب النصيحة"},{"id":"o4","text":"إكراه الناس دون صلاحية"},{"id":"o2","text":"التجسس والتشهير"}],"correct_id":"o1","explanation":"جعل الكتاب العلم والحكمة من أهم آداب الأمر بالمعروف والنهي عن المنكر.","page":30},{"id":"u01_l04_q167","lesson_id":"u01_l04","difficulty":"medium","prompt":"من الجهة التي قد تملك صلاحية التغيير باليد في مجال سلامة الغذاء؟","options":[{"id":"o4","text":"الطلاب خارج المدرسة وحدهم"},{"id":"o1","text":"المؤسسات الرقابية الرسمية المختصة"},{"id":"o3","text":"أي حساب مجهول على الإنترنت"},{"id":"o2","text":"كل مستهلك دون قيد قانوني"}],"correct_id":"o1","explanation":"ذكر الكتاب مؤسسة الغذاء والدواء ضمن الجهات التي تملك سلطة التغيير باليد بضوابط.","page":32},{"id":"u01_l04_q172","lesson_id":"u01_l04","difficulty":"medium","prompt":"ما معنى كون الأمر بالمعروف والنهي عن المنكر فرض كفاية؟","options":[{"id":"o2","text":"أن أداءه ممنوع على غير المعلمين"},{"id":"o3","text":"أنه يسقط عن المجتمع حتى لو لم يقم به أحد"},{"id":"o4","text":"أنه لا يتطلب علمًا ولا قدرة"},{"id":"o1","text":"إذا قام به من يكفي تحققت الكفاية وسقط الإثم عن الباقين"}],"correct_id":"o1","explanation":"نص الدرس على أنه فرض كفاية يقوم به من يكفي بحسب العلم والقدرة.","page":29},{"id":"u01_l04_q174","lesson_id":"u01_l04","difficulty":"medium","prompt":"لماذا شبّه الحديث أفراد المجتمع بركّاب سفينة عند الحديث عن المنكر؟","options":[{"id":"o2","text":"لأن لكل فرد الحق في الإضرار بالآخرين"},{"id":"o4","text":"لأن النصيحة تقتصر على شؤون السفر"},{"id":"o3","text":"لأن سلامة المجتمع لا علاقة لها بسلوك أفراده"},{"id":"o1","text":"لأن إهمال فساد بعضهم قد يضر بالمجتمع كله"}],"correct_id":"o1","explanation":"يؤكد مثل السفينة أن منع الضرر يحمي الجميع من عواقب المنكر.","page":30},{"id":"u01_l04_q176","lesson_id":"u01_l04","difficulty":"medium","prompt":"ماذا نستنتج من قصة الحسن والحسين في تصحيح الوضوء لرجل كبير؟","options":[{"id":"o3","text":"أن تصحيح العبادة لا يحتاج إلى مثال عملي"},{"id":"o1","text":"أن النصيحة غير المباشرة قد تحفظ كرامة المخطئ وتحقق التعلم"},{"id":"o2","text":"أن كشف الخطأ أمام الناس هو الطريقة الوحيدة للتعليم"},{"id":"o4","text":"أن المشورة لا تفيد في تصحيح السلوك"}],"correct_id":"o1","explanation":"تدل القصة على فاعلية الحكمة واللطف في تصحيح خطأ الوضوء.","page":31},{"id":"u01_l04_q181","lesson_id":"u01_l04","difficulty":"medium","prompt":"في مؤسسة سكت الجميع عن غش ظاهر مع قدرتهم على معالجته؛ ما الخلل في أداء فرض الكفاية؟","options":[{"id":"o2","text":"تحقق الكفاية بمجرد معرفة وقوع الغش"},{"id":"o3","text":"تحول السكوت إلى إقرار بفضيلة الغش"},{"id":"o1","text":"عدم قيام من يكفي بإزالة المنكر وفق الضوابط"},{"id":"o4","text":"انتهاء واجب النصيحة عند انتشار الخطأ"}],"correct_id":"o1","explanation":"تقتضي الكفاية أن يقوم بالأمر من يحقق الغرض مع العلم والقدرة.","page":29},{"id":"u01_l04_q183","lesson_id":"u01_l04","difficulty":"medium","prompt":"ما أثر إهمال أفراد السفينة محاولة أحدهم إحداث خرق فيها بحسب المثل النبوي؟","options":[{"id":"o4","text":"ازدياد سلامة السفينة بسبب الخرق"},{"id":"o3","text":"انتفاء مسؤولية بقية الركاب ولو استطاعوا المنع"},{"id":"o1","text":"امتداد الضرر إلى الركاب جميعًا"},{"id":"o2","text":"بقاء الضرر محصورًا في صاحب الخرق دائمًا"}],"correct_id":"o1","explanation":"مثل السفينة يوضح أن ترك المنكر يهدد السلامة العامة.","page":30},{"id":"u01_l04_q184","lesson_id":"u01_l04","difficulty":"hard","prompt":"طالب ينصح زميله سرًا ويذكر له أثر الخطأ على حقوق غيره؛ لماذا يعد هذا أقرب إلى الحكمة؟","options":[{"id":"o3","text":"لأن كل نصيحة يجب أن تكون عامة أمام الناس"},{"id":"o2","text":"لأنه يمنع الزميل من فهم خطئه"},{"id":"o1","text":"لأنه يجمع اللطف مع بيان المصلحة والضرر"},{"id":"o4","text":"لأن الحفاظ على الكرامة يلغي تصحيح الخطأ"}],"correct_id":"o1","explanation":"يؤكد الدرس الموعظة الحسنة والرفق والابتعاد عن التشهير.","page":30},{"id":"u01_l04_q185","lesson_id":"u01_l04","difficulty":"medium","prompt":"بماذا يستدل من مطالبة الناصح بأن يبدأ بإصلاح نفسه قبل مطالبة غيره؟","options":[{"id":"o1","text":"وجوب موافقة العمل لما يدعو إليه المرء"},{"id":"o3","text":"أن كلام الناصح يغني عن كل سلوك"},{"id":"o4","text":"أن القدوة لا تؤثر في قبول التوجيه"},{"id":"o2","text":"أن العاقل لا ينصح أحدًا مطلقًا"}],"correct_id":"o1","explanation":"جعل الكتاب العمل بما يأمر به المرء من آداب النصيحة.","page":31},{"id":"u01_l04_q187","lesson_id":"u01_l04","difficulty":"medium","prompt":"إذا لم يستطع المرء تغيير منكر بيده ولا بلسانه، فأي موقف يوافق مراتب التغيير؟","options":[{"id":"o1","text":"إنكاره بقلبه مع عدم الرضا عنه"},{"id":"o4","text":"إهمال الحكم لأن يده عاجزة"},{"id":"o3","text":"تعريض نفسه والناس لضرر أكبر"},{"id":"o2","text":"إعلان الرضا بالمنكر حتى لا يختلف مع الناس"}],"correct_id":"o1","explanation":"ذكر الحديث مرتبة القلب عند عدم القدرة على التغيير باليد أو اللسان.","page":32},{"id":"u01_l05_q094","lesson_id":"u01_l05","difficulty":"medium","prompt":"أي وصف أدق للحشر؟","options":[{"id":"o3","text":"زمن يسبق الحياة الدنيا"},{"id":"o1","text":"جمع المخلوقات بعد بعثها في مكان واحد"},{"id":"o4","text":"اسم لفصل من فصول السنة"},{"id":"o2","text":"تفرق الناس دون اجتماع"}],"correct_id":"o1","explanation":"الحشر هو جمع الخلق بعد بعثهم في أرض المحشر.","page":36},{"id":"u01_l05_q108","lesson_id":"u01_l05","difficulty":"medium","prompt":"ما أثر استحضار جزاء الآخرة عند إغراء الإنسان بكسب غير مشروع؟","options":[{"id":"o3","text":"تجاهل حقوق الآخرين"},{"id":"o4","text":"إلغاء التوبة من حياته"},{"id":"o2","text":"تقديم اللذة المؤقتة على المبدأ"},{"id":"o1","text":"ترك الوسيلة المحرمة وإن بدت مغرية"}],"correct_id":"o1","explanation":"يعد الدرس الابتعاد عن تحصيل الملذات بطرق غير مشروعة من آثار الإيمان بالآخرة.","page":38},{"id":"u01_l05_q121","lesson_id":"u01_l05","difficulty":"medium","prompt":"ما الأثر العملي الذي ينسجم مع الإيمان باليوم الآخر عند اتخاذ قرار أخلاقي؟","options":[{"id":"o3","text":"إنكار مسؤولية المرء عن أفعاله"},{"id":"o4","text":"حصر الاهتمام بالسمعة الاجتماعية"},{"id":"o2","text":"تقديم النفع العاجل ولو كان محرمًا"},{"id":"o1","text":"مراعاة الحساب والجزاء ولو غاب رقيب الناس"}],"correct_id":"o1","explanation":"يربط الدرس اليقين بالجزاء بتحسين سلوك الإنسان.","page":34},{"id":"u01_l05_q124","lesson_id":"u01_l05","difficulty":"hard","prompt":"طالب يخلط بين مرحلة البرزخ وحدث الحشر؛ ما التصحيح؟","options":[{"id":"o2","text":"البرزخ اسم لميزان الأعمال"},{"id":"o3","text":"الحشر مرحلة تسبق الموت الدنيوي"},{"id":"o4","text":"كلتا المرحلتين تعني تسلم الصحف"},{"id":"o1","text":"البرزخ يبدأ بعد الموت إلى البعث، والحشر جمع الناس بعد بعثهم"}],"correct_id":"o1","explanation":"عرّف الكتاب البرزخ بأنه بين الموت والبعث والحشر بأنه جمع الناس يوم القيامة.","page":35},{"id":"u01_l05_q133","lesson_id":"u01_l05","difficulty":"medium","prompt":"أي حدث يسبق خروج الناس من القبور بعد انتهاء الحياة الدنيا بحسب العرض؟","options":[{"id":"o4","text":"دخول الجنة"},{"id":"o3","text":"الشفاعة الصغرى"},{"id":"o1","text":"النفخ في الصور الذي تقع به الوفاة"},{"id":"o2","text":"عرض صحائف الأعمال"}],"correct_id":"o1","explanation":"يسرد الكتاب النفخ في الصور ضمن بداية أحداث يوم القيامة قبل البعث.","page":36},{"id":"u01_l05_q135","lesson_id":"u01_l05","difficulty":"medium","prompt":"عند طول انتظار الناس في المحشر، إلى مَن تنتهي طلبات الشفاعة لبدء الحساب؟","options":[{"id":"o1","text":"إلى النبي محمد ﷺ"},{"id":"o2","text":"إلى أصحاب المال"},{"id":"o4","text":"إلى العلماء في الدنيا"},{"id":"o3","text":"إلى الملائكة وحدهم"}],"correct_id":"o1","explanation":"ذكر الدرس شفاعة النبي ﷺ الكبرى لبدء الحساب.","page":37},{"id":"u01_l05_q138","lesson_id":"u01_l05","difficulty":"medium","prompt":"عندما تردع فكرة الحساب شخصًا عن كسب محرم سريع، أي أثر للإيمان بالآخرة يتجلى؟","options":[{"id":"o4","text":"إلغاء مسؤولية الشخص عن اختياره"},{"id":"o2","text":"اشتراط ترك الكسب كله"},{"id":"o1","text":"تقديم الثواب الأخروي على لذة محرمة"},{"id":"o3","text":"ضمان الثراء لكل مؤمن"}],"correct_id":"o1","explanation":"من آثار الإيمان بالآخرة تجنب الملذات غير المشروعة.","page":38},{"id":"u01_l05_q141","lesson_id":"u01_l05","difficulty":"medium","prompt":"لماذا لا تؤدي مشاهدة علامات يوم القيامة إلى معرفة موعدها يقينًا؟","options":[{"id":"o3","text":"لأن العلامات أحكام المواريث"},{"id":"o4","text":"لأن كل إنسان يحدد موعدها لنفسه"},{"id":"o1","text":"لأن توقيت الساعة من الغيب الذي اختص الله بعلمه"},{"id":"o2","text":"لأن العلامات وقعت كلها في عصر واحد"}],"correct_id":"o1","explanation":"يفرق الدرس بين العلامات الدالة على قرب الساعة وبين العلم بوقتها.","page":35},{"id":"u01_l05_q143","lesson_id":"u01_l05","difficulty":"medium","prompt":"ما الحدث الذي تنتهي به حياة الأحياء عند النفخة الأولى في الصور؟","options":[{"id":"o4","text":"العودة إلى الحياة الدنيا"},{"id":"o1","text":"الموت والهلاك بأمر الله"},{"id":"o2","text":"توزيع صحائف الأعمال"},{"id":"o3","text":"الدخول إلى الجنة"}],"correct_id":"o1","explanation":"تميّز صفحات الدرس النفخة الأولى وما يتبعها عن النفخة الثانية المرتبطة بالبعث.","page":36},{"id":"u01_l05_q144","lesson_id":"u01_l05","difficulty":"hard","prompt":"إذا وصف أحدهم الحشر بأنه إحياء الأموات من القبور فقط، فما الجزء الذي أغفله من تعريفه؟","options":[{"id":"o1","text":"جمع المبعوثين في أرض المحشر"},{"id":"o2","text":"الحياة في البرزخ"},{"id":"o3","text":"زمن ظهور علامات الساعة"},{"id":"o4","text":"النظر في أعمال الدنيا قبل الموت"}],"correct_id":"o1","explanation":"يفرق الكتاب بين البعث من القبور والحشر بجمع الخلق في موضع واحد.","page":36},{"id":"u01_l05_q147","lesson_id":"u01_l05","difficulty":"medium","prompt":"مؤمن يحرص على أداء حقوق الناس وهو يتذكر يوم الحساب؛ ما الأثر الذي يفسّر هذا الحرص؟","options":[{"id":"o3","text":"الركون إلى المال وحده"},{"id":"o4","text":"إهمال مسؤوليات المجتمع"},{"id":"o2","text":"الاستغناء عن العمل النافع"},{"id":"o1","text":"مراقبة العمل والاستعداد للجزاء"}],"correct_id":"o1","explanation":"من آثار الإيمان بالآخرة استقامة السلوك والمداومة على الصالحات.","page":38},{"id":"u01_l05_q148","lesson_id":"u01_l05","difficulty":"hard","prompt":"ما السبب المعرفي الذي يمنع وضع تفاصيل جازمة عن البرزخ بالاعتماد على التجربة المباشرة للأحياء؟","options":[{"id":"o4","text":"أن البرزخ يساوي مرحلة الدراسة"},{"id":"o2","text":"أن البرزخ جزء من تاريخ الغزوات"},{"id":"o1","text":"أن البرزخ عالم غيبي لا يُعلم منه إلا ما أخبر به الوحي"},{"id":"o3","text":"أن الشهادة البشرية تغني عن النص في كل غيب"}],"correct_id":"o1","explanation":"نص الدرس على عدم معرفة أحوال البرزخ إلا بما أخبر به الوحي.","page":39},{"id":"u01_l05_q153","lesson_id":"u01_l05","difficulty":"easy","prompt":"ما الذي يربط الإيمان بالله بالإيمان باليوم الآخر في توجيه السلوك؟","options":[{"id":"o2","text":"الاعتماد على المال وحده في تحديد الصواب"},{"id":"o3","text":"ترك العناية بحقوق الناس"},{"id":"o1","text":"استشعار المساءلة عند اختيار القول والفعل"},{"id":"o4","text":"إمكان تحديد موعد الساعة بالتجربة"}],"correct_id":"o1","explanation":"بيّن الدرس أن اقتران الإيمان بالله واليوم الآخر يدعم ضبط سلوك المؤمن.","page":35},{"id":"u01_l05_q154","lesson_id":"u01_l05","difficulty":"medium","prompt":"إذا فسّر أحدهم النفخة الثانية بأنها موت الأحياء، فما وجه الخطأ في ذلك؟","options":[{"id":"o2","text":"لأن النفختين تعنيان جمع الأعمال في الميزان"},{"id":"o1","text":"النفخة الثانية مرتبطة بالبعث بعد نفخة انتهاء الحياة"},{"id":"o3","text":"لأن النفخة الثانية تعني بداية الرسالة النبوية"},{"id":"o4","text":"لأن نفخ الصور من شؤون الدنيا المعتادة"}],"correct_id":"o1","explanation":"فرّق الكتاب بين النفخة الأولى للموت والثانية للبعث.","page":36},{"id":"u01_l05_q156","lesson_id":"u01_l05","difficulty":"hard","prompt":"شخص اختار ردّ مظلمة كان يمكن أن يخفيها عن الناس؛ أي أثر للإيمان بالآخرة يظهر في اختياره؟","options":[{"id":"o2","text":"الاعتقاد أن الحقوق تضيع بعد الموت"},{"id":"o3","text":"الاعتماد على إخفاء الخطأ لإلغاء المسؤولية"},{"id":"o1","text":"استحضار الحساب على الحقوق مهما خفي الفعل عن البشر"},{"id":"o4","text":"القول إن الحساب لا يشمل المعاملة بين الناس"}],"correct_id":"o1","explanation":"يربط الدرس الإيمان بالحساب بالتزام الحقوق والابتعاد عن المعاصي.","page":37},{"id":"u01_l05_q162","lesson_id":"u01_l05","difficulty":"medium","prompt":"ما الغرض من إخبار الناس بعلامات اليوم الآخر دون بيان وقت وقوعه؟","options":[{"id":"o2","text":"تمكينهم من تحديد موعد الساعة بالدقيقة"},{"id":"o1","text":"تنبيههم إلى التوبة والاستعداد بالأعمال الصالحة"},{"id":"o4","text":"حصر الاستعداد في مراقبة الظواهر"},{"id":"o3","text":"صرفهم عن مسؤوليات الحياة"}],"correct_id":"o1","explanation":"بيّن الدرس أن العلامات تدعو إلى اليقظة والتوبة مع بقاء وقت الساعة من الغيب.","page":34},{"id":"u01_l05_q165","lesson_id":"u01_l05","difficulty":"medium","prompt":"ما دلالة إعطاء المؤمن صحيفة عمله بيمينه وفق شرح أحداث القيامة؟","options":[{"id":"o3","text":"أن الحساب لا يشمل الصغائر"},{"id":"o4","text":"أن الناس يتبادلون الصحائف عشوائيًا"},{"id":"o1","text":"ارتباطه بالإيمان والعمل الصالح والبشرى"},{"id":"o2","text":"أن الصحيفة لا تتضمن أعمال الدنيا"}],"correct_id":"o1","explanation":"ذكر الدرس أن أهل الإيمان والعمل الصالح يأخذون كتبهم بأيمانهم.","page":37},{"id":"u01_l05_q174","lesson_id":"u01_l05","difficulty":"medium","prompt":"عندما يُبعث الناس من القبور، أي حدث يسبق جمعهم في المحشر؟","options":[{"id":"o1","text":"النفخة الثانية في الصور"},{"id":"o3","text":"دخول الجنة أو النار"},{"id":"o4","text":"توزيع أنصبة المواريث"},{"id":"o2","text":"الشفاعة الصغرى"}],"correct_id":"o1","explanation":"النفخة الثانية هي نفخة البعث ثم يكون حشر المخلوقات في مكان واحد.","page":36},{"id":"u01_l05_q183","lesson_id":"u01_l05","difficulty":"medium","prompt":"ما وجه اختلاف الحشر عن البعث ضمن ترتيب أحداث اليوم الآخر؟","options":[{"id":"o2","text":"الحشر هو الموت والبعث محاسبة المال"},{"id":"o3","text":"البعث دخول الجنة والحشر كتابة الأعمال"},{"id":"o4","text":"كلاهما اسم للحياة الدنيا قبل الوفاة"},{"id":"o1","text":"البعث خروج الأموات من القبور والحشر جمعهم للموقف"}],"correct_id":"o1","explanation":"فصلت خريطة الدرس بين نفخة البعث وحشر الخلائق للحساب.","page":36},{"id":"u01_l05_q188","lesson_id":"u01_l05","difficulty":"hard","prompt":"لماذا لا يمكن للإنسان وصف تفاصيل مرحلة البرزخ اعتمادًا على الملاحظة الدنيوية وحدها؟","options":[{"id":"o4","text":"لأن أحداثها تُعرف بحساب الأجرام"},{"id":"o2","text":"لأن البرزخ يقع قبل الولادة"},{"id":"o1","text":"لأن معرفتها متوقفة على ما أخبر به الوحي"},{"id":"o3","text":"لأن البرزخ هو اسم للحشر نفسه"}],"correct_id":"o1","explanation":"قرر الدرس أن الإنسان لا يعلم عن البرزخ إلا ما أخبر به الوحي.","page":39},{"id":"u01_l06_q105","lesson_id":"u01_l06","difficulty":"medium","prompt":"لماذا ينصح المجتهد بالرجوع إلى متخصص في العلوم المتعلقة بالمسألة الجديدة؟","options":[{"id":"o2","text":"لأن المختص يستغني عن الأدلة الشرعية"},{"id":"o1","text":"لفهم تفاصيلها قبل استنباط حكمها"},{"id":"o3","text":"لتقديم رأي واحد دون نقاش"},{"id":"o4","text":"لأن الأحكام مستقلة عن تصور الوقائع"}],"correct_id":"o1","explanation":"يؤكد الدرس أن الحكم على الشيء فرع عن تصوره.","page":43},{"id":"u01_l06_q108","lesson_id":"u01_l06","difficulty":"medium","prompt":"بعد عدم وجود حكم مباشر لقضية في الكتاب والسنة، ماذا فعل الخلفاء الراشدون؟","options":[{"id":"o2","text":"ألغوا مصادر التشريع"},{"id":"o1","text":"اجتهدوا وفق الأصول التي تعلموها"},{"id":"o3","text":"أوقفوا النظر في كل قضية"},{"id":"o4","text":"قدموا أهواء الناس على الأدلة"}],"correct_id":"o1","explanation":"وصف الكتاب رجوعهم إلى الوحي ثم الاجتهاد بضوابطه عند عدم النص.","page":42},{"id":"u01_l06_q110","lesson_id":"u01_l06","difficulty":"hard","prompt":"أي تمييز دقيق بين مجال الاجتهاد والحكم القطعي؟","options":[{"id":"o2","text":"كلاهما مفتوح لتغيير الحكم بحسب الرغبة"},{"id":"o1","text":"الأحكام القطعية لا تغير بالاجتهاد بينما يبحث المستجد الذي لا نص قطعي مباشر فيه"},{"id":"o3","text":"المستجدات لا يجوز بحثها أبدًا"},{"id":"o4","text":"القطعي يتغير بتفضيل رأي الجماعة"}],"correct_id":"o1","explanation":"حدد الكتاب مفهوم الاجتهاد واستثناء الأحكام القطعية من مجاله.","page":42},{"id":"u01_l06_q117","lesson_id":"u01_l06","difficulty":"medium","prompt":"أي مهمة علمية تقوم بها دائرة الإفتاء العام إلى جانب إصدار الفتاوى؟","options":[{"id":"o3","text":"تنظيم حركة المطارات"},{"id":"o1","text":"إعداد الدراسات والبحوث في القضايا المستجدة"},{"id":"o4","text":"تقرير أسعار السلع كافة"},{"id":"o2","text":"إدارة الامتحانات المدرسية"}],"correct_id":"o1","explanation":"من مهامها المذكورة إعداد البحوث والدراسات الإسلامية اللازمة للأمور المهمة.","page":45},{"id":"u01_l06_q118","lesson_id":"u01_l06","difficulty":"hard","prompt":"مفتٍ يدرك النصوص لكنه يجهل طبيعة تقنية جديدة؛ أي خطوة من منهج الاجتهاد تتعين عليه؟","options":[{"id":"o1","text":"فهم الواقعة بالرجوع إلى المختصين قبل الحكم عليها"},{"id":"o2","text":"إصدار فتوى فورية وفق الاسم الشائع"},{"id":"o4","text":"اعتبار كل تقنية جديدة محرمة دون بحث"},{"id":"o3","text":"تجاهل الجوانب الفنية للواقعة"}],"correct_id":"o1","explanation":"نص الكتاب على أن الحكم على الشيء فرع من تصوره وأن الرجوع إلى المختصين يعين على فهمه.","page":43},{"id":"u01_l06_q121","lesson_id":"u01_l06","difficulty":"medium","prompt":"كيف تسهم صفة «الواقعية» في قدرة الشريعة على معالجة الوقائع المتجددة؟","options":[{"id":"o4","text":"تتجاهل تغير وسائل الحياة"},{"id":"o2","text":"تمنع البحث في الوقائع الجديدة"},{"id":"o3","text":"تقتصر على عصر واحد"},{"id":"o1","text":"تراعي أوضاع الناس وتتعامل مع مستجدات حياتهم بضوابط"}],"correct_id":"o1","explanation":"أبرز المدخل الشمول والمرونة والواقعية التي تتيح معالجة المستجدات.","page":41},{"id":"u01_l06_q125","lesson_id":"u01_l06","difficulty":"medium","prompt":"أي شرط يساعد المجتهد على تفسير الدلالات الدقيقة للألفاظ في القرآن والسنة؟","options":[{"id":"o3","text":"كثرة المتابعين"},{"id":"o1","text":"التمكن من اللغة العربية"},{"id":"o2","text":"الشهرة على وسائل التواصل"},{"id":"o4","text":"القدرة على الخطابة دون علم"}],"correct_id":"o1","explanation":"عدّ الدرس التمكن من العربية من شروط المجتهد لفهم النصوص.","page":43},{"id":"u01_l06_q130","lesson_id":"u01_l06","difficulty":"medium","prompt":"أي نشاط علمي لدائرة الإفتاء العام في الأردن يختلف عن إصدار الفتاوى للأفراد؟","options":[{"id":"o3","text":"إدارة كل المستشفيات"},{"id":"o1","text":"نشر مجلة علمية محكمة في علوم الشريعة"},{"id":"o4","text":"إصدار رخص البناء"},{"id":"o2","text":"تحديد أسعار السلع يوميًا"}],"correct_id":"o1","explanation":"ذكر الإثراء إصدار مجلة علمية متخصصة بالبحوث الشرعية من مهام الدائرة.","page":45},{"id":"u01_l06_q132","lesson_id":"u01_l06","difficulty":"medium","prompt":"كيف تصرف الخلفاء الراشدون عندما لم يجدوا حكم الواقعة الجديدة في القرآن الكريم؟","options":[{"id":"o3","text":"قدموا العرف على النص دومًا"},{"id":"o1","text":"رجعوا إلى السنة النبوية قبل الاجتهاد"},{"id":"o2","text":"تركوا القضية دون نظر"},{"id":"o4","text":"أصدروا حكمًا بلا بحث"}],"correct_id":"o1","explanation":"ذكر الكتاب مراجعة القرآن ثم السنة ثم الاجتهاد وفق الأصول.","page":42},{"id":"u01_l06_q136","lesson_id":"u01_l06","difficulty":"medium","prompt":"هيئة فقهية تضم متخصصين في الطب والاقتصاد إلى جانب الفقهاء؛ ما الفائدة المباشرة لهذه المشاركة؟","options":[{"id":"o2","text":"إعفاء الفقهاء من دراسة الأدلة"},{"id":"o4","text":"السماح بتجاوز النصوص القطعية"},{"id":"o3","text":"تحويل الفتوى إلى تصويت شعبي"},{"id":"o1","text":"توضيح حقائق المسائل المتخصصة قبل الحكم فيها"}],"correct_id":"o1","explanation":"عدّ الدرس الاستفادة من خبرات المتخصصين ميزة للاجتهاد الجماعي.","page":44},{"id":"u01_l06_q142","lesson_id":"u01_l06","difficulty":"medium","prompt":"إذا كانت أنصبة الورثة محددة بنص قطعي، فلماذا لا يُعاد وضعها باجتهاد جديد؟","options":[{"id":"o3","text":"لأن المال لا يخضع لأحكام"},{"id":"o1","text":"لأن الاجتهاد لا يقع فيما كان قطعي الدلالة على الحكم"},{"id":"o2","text":"لأن الاجتهاد لا يرتبط بالشريعة أصلًا"},{"id":"o4","text":"لأن العلماء يختصون بالأمور الطبية فقط"}],"correct_id":"o1","explanation":"نص الدرس على منع الاجتهاد في الأحكام القطعية، وذكر أنصبة المواريث مثالًا.","page":42},{"id":"u01_l06_q144","lesson_id":"u01_l06","difficulty":"medium","prompt":"لماذا عُدّ امتلاك مهارات البحث والتفكير الناقد شرطًا مكمّلًا للمجتهد؟","options":[{"id":"o1","text":"ليستطيع فحص الأدلة ومعالجة المسائل المتجددة"},{"id":"o2","text":"ليستغني عن القرآن والسنة"},{"id":"o4","text":"ليحدد الحكم بحسب انطباعه"},{"id":"o3","text":"ليتجنب النظر في أقوال العلماء"}],"correct_id":"o1","explanation":"تضم شروط المجتهد العلم بالأصول والبحث والتفكير الناقد.","page":43},{"id":"u01_l06_q145","lesson_id":"u01_l06","difficulty":"medium","prompt":"أي سمة من سمات الاجتهاد الجماعي تساعد على كشف ثغرة في رأي فقيه واحد؟","options":[{"id":"o1","text":"تداول الأدلة والاعتراضات بين علماء مؤهلين"},{"id":"o3","text":"منع الاستعانة بالخبراء"},{"id":"o2","text":"الاكتفاء بعرض رأي واحد بلا مناقشة"},{"id":"o4","text":"عدم دراسة صورة المسألة"}],"correct_id":"o1","explanation":"من مزايا الاجتهاد الجماعي تعدد الآراء والحوارات واستعراض الأدلة.","page":44},{"id":"u01_l06_q146","lesson_id":"u01_l06","difficulty":"hard","prompt":"لماذا قد تحتاج مسألة طبية حديثة إلى فريق يجمع بين العلماء الشرعيين وأطباء متخصصين؟","options":[{"id":"o2","text":"لتحويل الطبيب وحده إلى واضع أحكام شرعية"},{"id":"o1","text":"لضبط الحقائق الطبية ثم بحث حكمها على ضوء الأدلة"},{"id":"o4","text":"لجعل الحكم تابعًا لأغلبية المرضى"},{"id":"o3","text":"لإلغاء نصوص الشريعة في الحالات الطبية"}],"correct_id":"o1","explanation":"ذكر الكتاب أن مشاركة المتخصصين تبين حقائق المسائل أمام الفقهاء.","page":44},{"id":"u01_l06_q152","lesson_id":"u01_l06","difficulty":"medium","prompt":"لماذا تصلح كيفية أداء الصلاة في الطائرة مثالًا لمسألة اجتهادية؟","options":[{"id":"o2","text":"لأن أصل وجوب الصلاة قابل للإلغاء"},{"id":"o3","text":"لأن الصلاة في الطائرة ليس لها علاقة بأحكام الشرع"},{"id":"o4","text":"لأن أي مسافر يستطيع وضع حكم دون علم"},{"id":"o1","text":"لوجود ظروف مستجدة تستلزم بحث تطبيق الحكم وفق الأصول"}],"correct_id":"o1","explanation":"وضعها الكتاب بين الأمثلة التي يمكن بحث أحكامها بالاجتهاد.","page":42},{"id":"u01_l06_q156","lesson_id":"u01_l06","difficulty":"medium","prompt":"أي خدمة علمية ذكرتها صفحة الإثراء ضمن مهام دائرة الإفتاء العام الأردنية؟","options":[{"id":"o1","text":"إصدار مجلة دورية تنشر بحوثًا شرعية محكّمة"},{"id":"o2","text":"الاقتصار على تنظيم أنشطة رياضية"},{"id":"o4","text":"تنظيم التجارة الخارجية بدل الإفتاء"},{"id":"o3","text":"إلغاء الدراسات المتعلقة بالقضايا المستجدة"}],"correct_id":"o1","explanation":"يذكر الكتاب إصدار مجلة علمية دورية متخصصة تنشر البحوث المحكّمة في علوم الشريعة الإسلامية ضمن مهام دائرة الإفتاء العام.","page":45}]$wall_questions$::jsonb)
